<script lang="ts">
  import {onMount,tick} from 'svelte';
  import type {WorkbenchState} from '../lib/workbench-state.js';
  import {loadContextCatalog} from '../lib/context-catalog.js';
  import {api} from '../lib/api.js';
  import type {DeviceAvailability} from '../../fngk/process-client.js';
  import {deviceLabelStore,resolveDeviceIdentity} from '../lib/device-identity.js';
  import {atlasDeviceColors,deviceAppearanceStore} from '../lib/device-appearance.js';
  import Database from '@lucide/svelte/icons/database';
  import Network from '@lucide/svelte/icons/network';
  import Rocket from '@lucide/svelte/icons/rocket';
  import SquareTerminal from '@lucide/svelte/icons/square-terminal';
  import PermanentPanelHeader from './PermanentPanelHeader.svelte';import AtlasInput from './ui/AtlasInput.svelte';
  export let state:WorkbenchState;
  let device:any;let label='';let editing=false;let appearanceRevision=0;
  // Availability is optional context: older FNGK CLIs or Signal releases lack it, so failures only hide the section.
  let availability:DeviceAvailability|null=null;let availabilityKey='';
  const reasonText=(reason:string|null)=>(reason??'unknown').replaceAll('_',' ');
  const span=(ms:number|null|undefined)=>{if(ms===null||ms===undefined)return '—';const s=Math.floor(ms/1000);return s<60?`${s}s`:s<3600?`${Math.floor(s/60)}m`:s<172800?`${Math.floor(s/3600)}h ${Math.floor(s/60)%60}m`:`${Math.floor(s/86400)}d`};
  async function loadAvailability(){const id=device?.device?.id,profile=state.snapshot().connection.profile??'',key=id?`${id}:${profile}:${device.online}`:'';if(key===availabilityKey)return;availabilityKey=key;if(!id){availability=null;return}try{const value=await api<DeviceAvailability>(`/api/device-availability?${new URLSearchParams({deviceId:id,limit:'5',...(profile?{profile}:{})})}`);if(availabilityKey===key)availability=value}catch{if(availabilityKey===key)availability=null}}
  async function refresh(){const catalog=await loadContextCatalog(false,state.snapshot().connection.profile);device=catalog.contexts.find((item:any)=>item.id===state.snapshot().contextId&&item.kind==='fngk-device');label=device?.device?.id?deviceLabelStore.getLabel(device.device.id)??resolveDeviceIdentity(device.device.id).label:'';void loadAvailability();}
  // Ask the workbench to size this panel to its content whenever the Device (or its availability) changes,
  // so the shortcuts sit right under the details instead of below empty space.
  let section:HTMLElement;let fittedFor='';
  async function fit(key:string){if(key===fittedFor)return;fittedFor=key;await tick();if(!section)return;const height=[...section.children].reduce((sum,child)=>{const style=getComputedStyle(child);return sum+child.getBoundingClientRect().height+(child.classList.contains('device-shortcuts')?0:parseFloat(style.marginTop)||0)+(parseFloat(style.marginBottom)||0)},0);window.dispatchEvent(new CustomEvent('atlas:fit-panel-height',{detail:{panelId:'atlas.device-details',height:height+2}}))}
  $: void fit(`${device?.device?.id??''}:${availability?.events?.length??-1}`);
  function save(){if(device?.device?.id)deviceLabelStore.setLabel(device.device.id,label);editing=false;}
  function setColor(color:(typeof atlasDeviceColors)[number]){if(device?.device?.id){deviceAppearanceStore.set(device.device.id,color);appearanceRevision++;}}
  function shortcut(name:'ports'|'deployment'|'database'|'terminal'){if(!device)return;if(name==='ports')window.dispatchEvent(new CustomEvent('atlas:open-ports',{detail:{contextId:device.id}}));else if(name==='deployment')window.dispatchEvent(new CustomEvent('atlas:open-deployment',{detail:{contextId:device.id}}));else if(name==='database')window.dispatchEvent(new CustomEvent('atlas:open-database',{detail:{contextId:device.id}}));else window.dispatchEvent(new CustomEvent('atlas:open-terminal',{detail:{contextId:device.id,target:device.id,title:device.name??'Terminal',newSession:true}}));}
  onMount(()=>{void refresh();const unsubscribe=state.subscribe(()=>void refresh()),appearanceChanged=()=>appearanceRevision++;window.addEventListener('atlas:device-appearance-changed',appearanceChanged);return()=>{unsubscribe();window.removeEventListener('atlas:device-appearance-changed',appearanceChanged)}});
</script>
<section bind:this={section} class="device-details" aria-label="Device details">
  <PermanentPanelHeader title="Device details" subtitle={device?.name??'Select a device'}><button class="collapse" title="Collapse device details" aria-label="Collapse device details" onclick={()=>window.dispatchEvent(new CustomEvent('atlas:toggle-panel-collapse',{detail:{panelId:'atlas.device-details'}}))}>−</button></PermanentPanelHeader>
  {#if device}{@const identity=resolveDeviceIdentity(device.device.id)}{@const color=appearanceRevision>=0?deviceAppearanceStore.get(device.device.id).color??identity.color:identity.color}
    <div class="device-profile"><b class="glyph" style={`--atlas-device-color:var(--atlas-device-${color})`}>{identity.glyph}</b><div><strong>{deviceLabelStore.getLabel(device.device.id)??identity.label}</strong><small>{device.name}</small></div><div class="device-colors" aria-label="Device color">{#each atlasDeviceColors as choice}<button title={`Use ${choice}`} aria-label={`Use ${choice}`} class:chosen={color===choice} style={`--device-choice:var(--atlas-device-${choice})`} onclick={()=>setColor(choice)}></button>{/each}</div></div>
    {#if editing}<form onsubmit={(event)=>{event.preventDefault();save()}}><AtlasInput bind:value={label} ariaLabel="Device label" maxlength={32}/><button>Save</button><button type="button" onclick={()=>editing=false}>Cancel</button></form>{:else}<div class="actions"><button class="rename" onclick={()=>editing=true}>Rename Atlas label</button><button onclick={()=>window.dispatchEvent(new Event('atlas:open-device-lifecycle'))}>Manage Device</button></div>{/if}
    <dl><div><dt>State</dt><dd>{device.online?'Online':'Offline'}</dd></div><div><dt>Platform</dt><dd>{device.device?.platform??'Unknown'}</dd></div><div><dt>Device ID</dt><dd>{device.device?.id}</dd></div></dl>
    {#if availability}{@const day=availability.summary.windows['24h']}{@const drop=availability.summary.lastDrop}
      <section class="device-availability" aria-label="Device availability"><h3>Availability</h3>
        <dl><div><dt>Uptime 24h</dt><dd>{day?.uptimePercent===null||day?.uptimePercent===undefined?'—':`${day.uptimePercent}%`}</dd></div><div><dt>Drops 24h</dt><dd>{day?.drops??0}</dd></div><div><dt>Last drop</dt><dd title={drop?new Date(drop.occurredAt).toLocaleString():''}>{drop?reasonText(drop.reason):'None recorded'}</dd></div></dl>
        <ol>{#each availability.events as event (event.id)}<li class:online={event.state==='online'}><i></i><span>{reasonText(event.reason)}{#if event.agentReport?.cause}<small> · agent: {reasonText(String(event.agentReport.cause))}</small>{/if}</span><time datetime={event.occurredAt}>{new Date(event.occurredAt).toLocaleString()}</time></li>{/each}</ol>
        {#if drop?.durationMs}<p>Online for {span(drop.durationMs)} before the last drop.</p>{/if}
      </section>
    {/if}
    <footer class="device-shortcuts" aria-label="Device shortcuts"><button title="Open published ports" onclick={()=>shortcut('ports')}><Network size={14}/><span>Ports</span></button><button title="Open deployments" onclick={()=>shortcut('deployment')}><Rocket size={14}/><span>Deploy</span></button><button title="Open databases" onclick={()=>shortcut('database')}><Database size={14}/><span>Data</span></button><button title="Open terminal" onclick={()=>shortcut('terminal')}><SquareTerminal size={14}/><span>Terminal</span></button></footer>
  {:else}<p>Select an FNGK device to inspect its local Atlas identity and connection state.</p>{/if}
</section>
<style>.device-availability{display:grid;gap:4px;margin:8px 0}.device-availability h3{margin:0;font-size:11px;font-weight:600}.device-availability ol{display:grid;gap:2px;margin:0;padding:0;list-style:none}.device-availability li{display:flex;align-items:center;gap:6px}.device-availability li span{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.device-availability li i{width:6px;height:6px;border-radius:50%;background:var(--atlas-danger,#ef4444)}.device-availability li.online i{background:var(--atlas-success,#84cc16)}.device-availability time,.device-availability small,.device-availability p{opacity:.7}.device-availability p{margin:0}.device-details{display:flex;flex-direction:column;height:100%;padding:0 10px;overflow:auto;font-size:11px}.device-details>:global(.atlas-permanent-header){position:sticky;top:0;z-index:1;flex:none;margin:0 -10px}.device-profile{display:flex;gap:8px;align-items:center;padding-top:10px}.device-profile>div{min-width:0;flex:1}.collapse{width:24px;height:24px;border:0;background:transparent} .glyph{display:grid;place-items:center;width:28px;height:28px;border-radius:50%;color:var(--atlas-device-color);background:color-mix(in srgb,var(--atlas-device-color) 20%,transparent)}small,dt,p{color:var(--atlas-muted)}small{display:block}.device-details form,.actions{display:flex;gap:4px;margin-top:10px}.device-details form :global(.atlas-input){min-width:0;flex:1}.rename{margin-top:0}dl{margin:10px 0;display:grid;gap:7px}dl div{display:grid;grid-template-columns:70px 1fr;gap:6px}dt,dd{margin:0}dd{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.device-shortcuts{position:sticky;bottom:0;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:3px;margin:auto -10px 0;padding:5px 10px;border-top:1px solid var(--atlas-border);background:var(--atlas-surface)}.device-shortcuts button{display:grid;justify-items:center;gap:2px;min-width:0;border:0;background:transparent;padding:4px 1px;color:var(--atlas-muted);font-size:9px}.device-shortcuts button:hover{color:var(--atlas-text);background:var(--atlas-hover)}.device-shortcuts span{overflow:hidden;text-overflow:ellipsis;max-width:100%}.device-colors{display:flex;flex:none;gap:4px}.device-colors button{display:block;width:14px;height:14px;padding:0;border:2px solid transparent;border-radius:50%;background:var(--device-choice)}.device-colors button.chosen{border-color:var(--atlas-text);box-shadow:0 0 0 1px var(--atlas-surface)}</style>
